(3691924, 514972, 77196, '<td valign="top">Here''s an example of why shooting on an overcast day with even lighting is preferred. The split personality of shadow &amp; sun really hurts this photo.</td>', 'Here''s an example of why shooting on an overcast day with even lighting is preferred. The split personality of shadow & sun really hurts this photo.', '2007-05-24 18:29:19.000000', NULL, 1),
(3691927, 518126, 77196, '<td valign="top">A tighter crop (2 shells, no more than 3) would make this shot better.</td>', 'A tighter crop (2 shells, no more than 3) would make this shot better.', '2007-05-24 18:30:07.000000', NULL, 1),
(3691934, 518963, 77196, '<td valign="top">Porsche! Yes! Excellent composition, nice progression of lighting from dark lower left to light right edge. Only possible distraction is hot spot at top left of light.</td>', 'Porsche! Yes! Excellent composition, nice progression of lighting from dark lower left to light right edge. Only possible distraction is hot spot at top left of light.', '2007-05-24 18:32:18.000000', NULL, 1),
(3691939, 514073, 77196, '<td valign="top">Good try. Sharper focus is needed and maybe a tighter crop. Keep experimenting - at least you can see the image in the droplet. I haven''t got any of these types of shots to turn out yet.</td>', 'Good try. Sharper focus is needed and maybe a tighter crop. Keep experimenting - at least you can see the image in the droplet. I haven''t got any of these types of shots to turn out yet.', '2007-05-24 18:33:23.000000', NULL, 1),
