(3699456, 518590, 74078, '<td valign="top">Perhaps some sort of difuser on the flash might have helped this image to a higher score. Still, I like the construction and the way you have taken something simple and turned it into a good entry. 8</td>', 'Perhaps some sort of difuser on the flash might have helped this image to a higher score. Still, I like the construction and the way you have taken something simple and turned it into a good entry. 8', '2007-05-27 03:18:40.000000', NULL, 1),
(3699460, 517963, 74078, '<td valign="top">Outstanding work. Crisp and clear. Great opportunistic shot which resulted in a great colour cast throughout your image. 10</td>', 'Outstanding work. Crisp and clear. Great opportunistic shot which resulted in a great colour cast throughout your image. 10', '2007-05-27 03:20:38.000000', NULL, 1),
(3699462, 515602, 74078, '<td valign="top">Looks like one of the images that you can stare at for hours and something will appear. Nice work</td>', 'Looks like one of the images that you can stare at for hours and something will appear. Nice work', '2007-05-27 03:21:15.000000', NULL, 1),
(3699479, 515147, 74078, '<td valign="top">Noisy and underexposed IMO Very Grainy in the face of the clock. Better lighting would have improved this image a bit. Better positioning would also improve the overall quality. At present it sits high and right of centre, with no apparent need. Good Luck</td>', 'Noisy and underexposed IMO Very Grainy in the face of the clock. Better lighting would have improved this image a bit. Better positioning would also improve the overall quality. At present it sits high and right of centre, with no apparent need. Good Luck', '2007-05-27 03:29:13.000000', NULL, 1),
