(3704022, 517796, 79095, '<td valign="top">Nice idea. But I find myself wanting a bit more ''story''. Perhaps some foreground or a bit more of the wall?</td>', 'Nice idea. But I find myself wanting a bit more ''story''. Perhaps some foreground or a bit more of the wall?', '2007-05-28 10:16:12.000000', NULL, 1),
(3704029, 515925, 79095, '<td valign="top">Nice idea, but the photo would greatly benefit from getting some nice soft light in there to bring out all those shapes. It''s quite dark as is.</td>', 'Nice idea, but the photo would greatly benefit from getting some nice soft light in there to bring out all those shapes. It''s quite dark as is.', '2007-05-28 10:17:30.000000', NULL, 1),
(3704035, 519028, 79095, '<td valign="top">I really like this. Nice capture of some straight line patterns in nature (unusual). The cows give context to the subject (the waterlines). Very cool.</td>', 'I really like this. Nice capture of some straight line patterns in nature (unusual). The cows give context to the subject (the waterlines). Very cool.', '2007-05-28 10:18:35.000000', NULL, 1),
(3704379, 518624, 33352, '<td valign="top">I see the shapes but the processing has too much grain.</td>', 'I see the shapes but the processing has too much grain.', '2007-05-28 11:40:52.000000', NULL, 1),
(3704426, 518062, 76556, '<td valign="top">cool</td>', 'cool', '2007-05-28 11:51:36.000000', NULL, 1),
(3704697, 514188, 51030, '<td valign="top">Beautiful lines and curves.</td>', 'Beautiful lines and curves.', '2007-05-28 12:59:24.000000', NULL, 1),
(3704783, 518714, 60275, '<td valign="top">The color cast is too strong (maybe wrong white balance). Also, there is too much detail for a 640px frame.</td>', 'The color cast is too strong (maybe wrong white balance). Also, there is too much detail for a 640px frame.', '2007-05-28 13:20:53.000000', NULL, 1),
