(3704917, 518597, 34255, '<td valign="top">Strange. Rather poor image quality, also.</td>', 'Strange. Rather poor image quality, also.', '2007-05-28 13:59:29.000000', NULL, 1),
(3704924, 518748, 34255, '<td valign="top">I wish it were in color.</td>', 'I wish it were in color.', '2007-05-28 14:00:48.000000', NULL, 1),
