(3705200, 515592, 77196, '<td valign="top">Detail on the near end is fantastic - but front of bench detail is washed out - a higher shutter speed with fill flash may have given a better result. I''m not positive whether it is just because the far bench is washed out, but I think the shot would be stronger without anything past its near leg.</td>', 'Detail on the near end is fantastic - but front of bench detail is washed out - a higher shutter speed with fill flash may have given a better result. I''m not positive whether it is just because the far bench is washed out, but I think the shot would be stronger without anything past its near leg.', '2007-05-28 16:05:55.000000', NULL, 1),
(3705332, 514306, 5885, '<td valign="top">That''s my kind of shape right there :-)</td>', 'That''s my kind of shape right there :-)', '2007-05-28 16:44:43.000000', NULL, 1),
(3705358, 518631, 5885, '<td valign="top">Nice legs and great use of silhouette.</td>', 'Nice legs and great use of silhouette.', '2007-05-28 16:48:34.000000', NULL, 1),
(3705364, 518707, 5885, '<td valign="top">I love this shot for some reason :-) One of the most interesting in the challenge, so far.</td>', 'I love this shot for some reason :-) One of the most interesting in the challenge, so far.', '2007-05-28 16:50:05.000000', NULL, 1),
(3705374, 516314, 5885, '<td valign="top">Kegs! :-)</td>', 'Kegs! :-)', '2007-05-28 16:52:03.000000', NULL, 1),
(3705380, 518289, 5885, '<td valign="top">Awesome shot!</td>', 'Awesome shot!', '2007-05-28 16:53:28.000000', NULL, 1),
(3705387, 515856, 5885, '<td valign="top">Beautiful! Top pick.</td>', 'Beautiful! Top pick.', '2007-05-28 16:54:58.000000', NULL, 1),
