(3708773, 517878, 59194, '<td valign="top">Great silhouette</td>', 'Great silhouette', '2007-05-29 13:35:02.000000', NULL, 1),
(3708810, 517362, 59194, '<td valign="top">Great reflections.  I''d suggest cropping out the feet on the left side, even if it means losing some of the car fender.  Maybe even cropping the ground too - I think it would help bring out the shape of the hood and the reflections.</td>', 'Great reflections.  I''d suggest cropping out the feet on the left side, even if it means losing some of the car fender.  Maybe even cropping the ground too - I think it would help bring out the shape of the hood and the reflections.', '2007-05-29 13:41:53.000000', NULL, 1),
(3708858, 518247, 59194, '<td valign="top">Cool shot...turned on it''s side...?</td>', 'Cool shot...turned on it''s side...?', '2007-05-29 13:52:59.000000', NULL, 1),
(3709139, 514906, 28070, '<td valign="top">Nice shapes.  The lighting could use some enhancement.  Good blurred out background, but the big white space (or the sky I suppose) in between the green leaves is distracting.  If the whole back was green or white or leaves and spaces all over the background.</td>', 'Nice shapes.  The lighting could use some enhancement.  Good blurred out background, but the big white space (or the sky I suppose) in between the green leaves is distracting.  If the whole back was green or white or leaves and spaces all over the background.', '2007-05-29 15:02:15.000000', NULL, 1),
(3709179, 518430, 28070, '<td valign="top">The blue of the sky doesn''t contrast well with the color of the structure.  Maybe 5000 yrs ago when they were either painted or newly quarried and shaped.    Maybe they are just in need of more light.  Yeah I think that is it.  More light on the Columns and less saturation of the Nitrogen (atmosphere).</td>', 'The blue of the sky doesn''t contrast well with the color of the structure.  Maybe 5000 yrs ago when they were either painted or newly quarried and shaped.    Maybe they are just in need of more light.  Yeah I think that is it.  More light on the Columns and less saturation of the Nitrogen (atmosphere).', '2007-05-29 15:10:38.000000', NULL, 1),
(3709360, 519020, 62249, '<td valign="top">It''s an okay photo, just not particularly original.</td>', 'It''s an okay photo, just not particularly original.', '2007-05-29 16:07:25.000000', NULL, 1),
(3709361, 518917, 62249, '<td valign="top">A potentially interesting subject, but the fisheye distortion is overwhelming.</td>', 'A potentially interesting subject, but the fisheye distortion is overwhelming.', '2007-05-29 16:08:54.000000', NULL, 1),
(3709364, 513945, 62249, '<td valign="top">Decent portrait but not a fabulous fit for the challenge topic.</td>', 'Decent portrait but not a fabulous fit for the challenge topic.', '2007-05-29 16:09:53.000000', NULL, 1),
(3709371, 518633, 62249, '<td valign="top">Cute idea. Needs to be sharper.</td>', 'Cute idea. Needs to be sharper.', '2007-05-29 16:12:13.000000', NULL, 1),
(3709380, 516186, 62249, '<td valign="top">This needs more of a focal point. There''s just too much to look at, so it''s hard to figure out which shape to pay attention to.</td>', 'This needs more of a focal point. There''s just too much to look at, so it''s hard to figure out which shape to pay attention to.', '2007-05-29 16:15:52.000000', NULL, 1),
(3709391, 515853, 62249, '<td valign="top">Interesting building, but for a challenge on shapes, it might work better to focus on a single shape instead of so many (the parapet, the stairs, the gridded windows, the trees, the folding chairs, etc.)</td>', 'Interesting building, but for a challenge on shapes, it might work better to focus on a single shape instead of so many (the parapet, the stairs, the gridded windows, the trees, the folding chairs, etc.)', '2007-05-29 16:18:42.000000', NULL, 1),
(3709399, 515198, 62249, '<td valign="top">Potentially interesting. Try again with the emphasis on the glass &amp; child''s face, and lose the balls.</td>', 'Potentially interesting. Try again with the emphasis on the glass & child''s face, and lose the balls.', '2007-05-29 16:21:57.000000', NULL, 1),
(3709407, 515193, 62249, '<td valign="top">Too many distracting elements (child, flower, diagonal line running through squares, crud on surface in background, dark shape protruding into second row of squares in upper left).</td>', 'Too many distracting elements (child, flower, diagonal line running through squares, crud on surface in background, dark shape protruding into second row of squares in upper left).', '2007-05-29 16:23:30.000000', NULL, 1),
(3709409, 518720, 62249, '<td valign="top">Nice. I like the high contrast and the stark color palette.</td>', 'Nice. I like the high contrast and the stark color palette.', '2007-05-29 16:24:21.000000', NULL, 1),
(3709412, 515147, 62249, '<td valign="top">Needs more interesting lighting and sharper focus.</td>', 'Needs more interesting lighting and sharper focus.', '2007-05-29 16:25:38.000000', NULL, 1),
(3709418, 517277, 62249, '<td valign="top">Not sharp enough, but interesting shadow effect, and I like the colors and geometry of this shot.</td>', 'Not sharp enough, but interesting shadow effect, and I like the colors and geometry of this shot.', '2007-05-29 16:26:58.000000', NULL, 1),
(3709424, 518714, 62249, '<td valign="top">Needs more of a focal point. The blue flowers in foreground are nice, but the dominant shapes in the photo are the tree trunks, and they''re not very interesting.</td>', 'Needs more of a focal point. The blue flowers in foreground are nice, but the dominant shapes in the photo are the tree trunks, and they''re not very interesting.', '2007-05-29 16:29:21.000000', NULL, 1),
