(3722812, 514344, 79284, '<td valign="top">Nice composition but  if the background is dark it will give a grate rilief.</td>', 'Nice composition but  if the background is dark it will give a grate rilief.', '2007-06-01 08:17:29.000000', NULL, 0),
(3723198, 515619, 67697, '<td valign="top">Beautiful lighting on a beautiful subject.  Love that you have not washed out any detail on the bird''s feathers (as I would have done lol).  Nice job!</td>', 'Beautiful lighting on a beautiful subject.  Love that you have not washed out any detail on the bird''s feathers (as I would have done lol).  Nice job!', '2007-06-01 10:02:48.000000', NULL, 0),
(3723213, 514188, 67697, '<td valign="top">This is a strong shot - great perspective.  I feel a sense of vertigo coming on now.  :)  Congrats on the ribbon!</td>', 'This is a strong shot - great perspective.  I feel a sense of vertigo coming on now.  :)  Congrats on the ribbon!', '2007-06-01 10:06:58.000000', NULL, 0),
(3723221, 517022, 67697, '<td valign="top">This is a lovely shot and quite symbolic.  Are those rose petals too?  Nice touch.  Too bad this did not score higher!</td>', 'This is a lovely shot and quite symbolic.  Are those rose petals too?  Nice touch.  Too bad this did not score higher!', '2007-06-01 10:08:26.000000', NULL, 0),
