(3724200, 517878, 51538, '<td valign="top">I like the placement of the ship-shape in the image.  Certainly a pleasant night to shoot.</td>', 'I like the placement of the ship-shape in the image.  Certainly a pleasant night to shoot.', '2007-06-01 13:50:43.000000', NULL, 0),
(3724419, 517499, 67553, '<td valign="top">Robert, that''s an awesome shot, and I really like the detailed comments you left with one.  Nice job, and congrats on the blue!</td>', 'Robert, that''s an awesome shot, and I really like the detailed comments you left with one.  Nice job, and congrats on the blue!', '2007-06-01 14:49:41.000000', NULL, 0),
